toolCalls.commandLine:
const patch = "*** Begin Patch
*** Add File: src/styles/app.css
+:root {
+  --bg: #edece6;
+  --side: #f5f4ef;
+  --card: #fff;
+  --ink: #121210;
+  --ink-2: #5a584f;
+  --ink-3: #8d8b80;
+  --line: rgba(18,18,16,.12);
+  --line-2: rgba(18,18,16,.065);
+  --lime: #c9fa46;
+  --lime-dark: #b7ea3b;
+  --sans: "Geist", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+  --mono: "Geist Mono", ui-monospace, monospace;
+  --side-width: 264px;
+  --ease: cubic-bezier(.22,.7,.2,1);
+}
+* { box-sizing: border-box; }
+html { background: var(--bg); color: var(--ink); -webkit-text-size-adjust: 100%; }
+body { margin: 0; font-family: var(--sans); font-size: 16px; line-height: 1.5; -webkit-font-smoothing: antialiased; }
+button, input { font: inherit; color: inherit; }
+button { border: 0; background: none; cursor: pointer; }
+button:focus-visible, a:focus-visible, input:focus-visible { outline: 2px solid #668c00; outline-offset: 3px; }
+a { color: inherit; text-decoration: none; }
+img { display: block; max-width: 100%; }
+::selection { background: var(--lime); }
+.app-shell { display: flex; min-height: 100vh; }
+.page { flex: 1; width: calc(100% - var(--side-width)); min-width: 0; }
+.eyebrow { margin: 0; color: var(--ink-3); font: 500 10px/1.3 var(--mono); letter-spacing: .13em; text-transform: uppercase; }
+.button { min-height: 43px; padding: 0 18px; border-radius: 11px; display: inline-flex; align-items: center; justify-content: center; gap: 10px; font-weight: 650; font-size: 13px; transition: transform .18s, background .18s; }
+.button:hover { transform: translateY(-1px); }
+.button svg { width: 17px; }
+.button--dark { color: white; background: var(--ink); }
+.button--lime { background: var(--lime); color: var(--ink); }
+.button--lime:hover { background: var(--lime-dark); }
+.text-link { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 650; }
+.text-link svg { width: 16px; }
+
+/* Sidebar */
+.sidebar { position: sticky; z-index: 30; top: 0; width: var(--side-width); height: 100vh; flex: 0 0 var(--side-width); padding: 22px 16px 18px; overflow: auto; background: var(--side); border-right: 1px solid var(--line); display: flex; flex-direction: column; }
+.sidebar::-webkit-scrollbar { width: 7px; }
+.sidebar::-webkit-scrollbar-thumb { background: rgba(0,0,0,.1); border-radius: 10px; }
+.brand { height: 39px; margin: 0 8px 17px; display: flex; align-items: center; gap: 9px; letter-spacing: -.035em; }
+.brand__bolt { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; flex: none; background: var(--ink); color: var(--lime); }
+.brand__bolt svg { width: 16px; height: 16px; }
+.brand strong { font-size: 17px; font-weight: 740; }
+.brand em { margin-left: -4px; color: var(--ink-2); font-size: 17px; font-weight: 400; }
+.side-nav { display: flex; flex-direction: column; gap: 2px; }
+.nav-item { width: 100%; min-height: 39px; padding: 0 12px; border-radius: 11px; display: flex; align-items: center; gap: 12px; color: var(--ink-2); font-size: 14px; font-weight: 480; text-align: left; transition: background .17s, color .17s; }
+.nav-item:hover, .nav-item.is-active { background: rgba(18,18,16,.06); color: var(--ink); }
+.nav-item.is-active { font-weight: 620; }
+.nav-item svg { width: 18px; height: 18px; }
+.new-badge { margin-left: auto; padding: 2px 6px; border-radius: 5px; background: var(--lime); color: var(--ink); font: 600 8px/1.3 var(--mono); letter-spacing: .07em; }
+.side-label { margin: 20px 12px 7px; color: var(--ink-3); font: 500 9px/1.4 var(--mono); letter-spacing: .14em; text-transform: uppercase; }
+.category-list { display: flex; flex-direction: column; }
+.category { width: 100%; min-height: 34px; padding: 0 12px; border-radius: 9px; display: flex; align-items: center; gap: 11px; color: var(--ink-2); font-size: 13.5px; text-align: left; }
+.category:hover { background: rgba(18,18,16,.05); color: var(--ink); }
+.category > span:last-child { margin-left: auto; color: var(--ink-3); font: 500 10px var(--mono); }
+.category__dot { width: 8px; height: 8px; border-radius: 50%; flex: none; background: var(--ink); opacity: .5; }
+.category.is-active { color: var(--ink); font-weight: 620; }
+.category.is-active .category__dot { opacity: 1; background: var(--lime); box-shadow: 0 0 0 3px rgba(201,250,70,.35); }
+.sidebar__footer { margin-top: auto; padding-top: 22px; }
+.seller-card { min-height: 86px; padding: 12px; border: 1px solid var(--line); border-radius: 13px; background: rgba(255,255,255,.6); display: grid; grid-template-columns: 24px 1fr; column-gap: 9px; }
+.seller-card svg { width: 20px; grid-row: 1/3; margin-top: 2px; }
+.seller-card strong { font-size: 13px; }
+.seller-card span { color: var(--ink-2); font-size: 11.5px; line-height: 1.4; }
+.side-actions { margin-top: 10px; display: flex; align-items: center; gap: 13px; }
+.side-actions .button { min-height: 36px; padding: 0 15px; font-size: 11px; }
+.side-actions button { font-size: 11px; font-weight: 600; text-decoration: underline; text-underline-offset: 3px; }
+.sidebar__footer small { margin-top: 15px; display: flex; color: var(--ink-3); font-size: 9px; }
+.sidebar__footer small span { margin-left: auto; color: var(--ink-2); }
+.mobile-head, .dock, .scrim { display: none; }
+
+/* Storefront controls */
+.storefront { min-height: 100vh; }
+.topbar { position: sticky; z-index: 20; top: 0; padding: 13px 18px 0; background: rgba(237,236,230,.9); border-bottom: 1px solid transparent; backdrop-filter: blur(18px); }
+.filter-row { min-height: 48px; padding: 5px; border: 1px solid var(--line); border-radius: 14px; background: rgba(255,255,255,.78); box-shadow: 0 3px 18px rgba(18,18,16,.035); display: flex; align-items: center; }
+.model-tabs, .sort-tabs { display: flex; align-items: center; gap: 2px; }
+.model-tabs button, .sort-tabs button { height: 37px; padding: 0 13px; border-radius: 10px; color: var(--ink-2); display: flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 540; white-space: nowrap; }
+.model-tabs button svg { width: 15px; }
+.model-tabs button:hover, .sort-tabs button:hover { color: var(--ink); background: var(--line-2); }
+.model-tabs button.is-active { background: var(--ink); color: white; }
+.sort-tabs { margin-left: auto; padding-left: 7px; border-left: 1px solid var(--line); }
+.sort-tabs button { height: 29px; padding: 0 10px; font: 500 10px var(--mono); letter-spacing: .03em; text-transform: uppercase; }
+.sort-tabs button.is-active { color: var(--ink); background: var(--lime); }
+.search-trigger { width: 36px; height: 36px; margin-left: 5px; border-radius: 10px; display: grid; place-items: center; }
+.search-trigger:hover { background: var(--line-2); }
+.search-trigger svg { width: 18px; }
+.search-reveal { height: 0; max-width: 720px; margin: 0 auto; overflow: hidden; opacity: 0; display: flex; align-items: center; transition: height .3s var(--ease), opacity .2s, margin .3s; }
+.search-reveal.is-open { height: 58px; margin-top: 5px; opacity: 1; }
+.search-reveal > svg { width: 18px; flex: none; color: var(--ink-3); }
+.search-reveal input { width: 100%; height: 45px; padding: 0 12px; background: transparent; border: 0; outline: 0; font-size: 14px; }
+.search-reveal input::placeholder { color: var(--ink-3); }
+.search-reveal button { color: var(--ink-2); font: 500 10px var(--mono); text-transform: uppercase; }
+.gallery-wrap { padding: 29px 18px 70px; }
+.gallery-heading { margin: 0 2px 25px; display: flex; align-items: end; justify-content: space-between; gap: 30px; }
+.gallery-heading h1, .page-title h1, .analytics-head h1 { margin: 5px 0 0; font-size: clamp(29px,3vw,47px); line-height: 1.02; letter-spacing: -.055em; }
+.gallery-heading h1 span, .page-title h1 span, .analytics-head h1 span { color: #86b800; }
+.gallery-heading > p { margin: 0 0 3px; color: var(--ink-3); font: 500 10px var(--mono); text-transform: uppercase; letter-spacing: .08em; }
+
+/* Real image masonry */
+.masonry { columns: 5 218px; column-gap: 14px; opacity: 1; transition: opacity .15s; }
+.masonry.is-loading { opacity: .64; }
+.prompt-card { position: relative; width: 100%; margin: 0 0 14px; border-radius: 13px; overflow: hidden; break-inside: avoid; background: #d8d6ce; box-shadow: 0 1px 0 rgba(0,0,0,.04); animation: card-in .5s both var(--ease); }
+@keyframes card-in { from { opacity: 0; transform: translateY(10px); } }
+.prompt-card__preview { width: 100%; padding: 0; display: block; }
+.prompt-card__preview img { width: 100%; aspect-ratio: var(--ratio); object-fit: cover; transition: transform .55s var(--ease), filter .3s; }
+.prompt-card__overlay { position: absolute; inset: 0; padding: 11px; pointer-events: none; display: flex; flex-direction: column; justify-content: space-between; color: white; background: linear-gradient(to bottom,rgba(0,0,0,.28),transparent 36%,transparent 52%,rgba(0,0,0,.78)); opacity: 0; transition: opacity .25s; }
+.prompt-card:hover .prompt-card__overlay, .prompt-card:focus-within .prompt-card__overlay { opacity: 1; }
+.prompt-card:hover img { transform: scale(1.025); filter: saturate(1.03); }
+.prompt-card__overlay button, .prompt-card__overlay a { pointer-events: auto; }
+.card-top { display: flex; align-items: center; justify-content: space-between; }
+.card-top > span { padding: 5px 8px; border-radius: 7px; background: rgba(18,18,16,.62); backdrop-filter: blur(6px); font: 500 8.5px var(--mono); letter-spacing: .08em; text-transform: uppercase; }
+.card-top button { width: 31px; height: 31px; border-radius: 9px; background: rgba(255,255,255,.92); color: var(--ink); display: grid; place-items: center; }
+.card-top button svg { width: 16px; }
+.is-saved .card-top button { background: var(--lime); }
+.card-bottom h2 { margin: 0 0 9px; max-width: 94%; color: white; font-size: 16px; line-height: 1.12; letter-spacing: -.025em; text-shadow: 0 1px 10px rgba(0,0,0,.2); }
+.card-bottom > div { display: flex; align-items: center; justify-content: space-between; }
+.card-bottom strong { font-size: 12px; }
+.card-bottom strong.is-free { color: var(--lime); }
+.card-bottom button { height: 30px; padding: 0 10px; border-radius: 8px; background: var(--lime); color: var(--ink); display: flex; align-items: center; gap: 5px; font-size: 10px; font-weight: 700; }
+.card-bottom button svg { width: 13px; }
+.saved-mark { position: absolute; z-index: 3; top: -1px; right: 17px; width: 25px; height: 31px; padding: 6px 5px 7px; border-radius: 0 0 6px 6px; background: var(--lime); color: var(--ink); pointer-events: none; }
+.saved-mark svg { width: 15px; fill: currentColor; }
+.empty-state { min-height: 410px; border: 1px dashed var(--line); border-radius: 18px; display: flex; align-items: center; justify-content: center; flex-direction: column; text-align: center; }
+.empty-state > svg { width: 32px; color: var(--ink-3); }
+.empty-state h2 { margin: 15px 0 4px; font-size: 24px; letter-spacing: -.04em; }
+.empty-state p { margin: 0 0 19px; color: var(--ink-2); }
+
+/* Modal */
+.modal { position: fixed; z-index: 80; inset: 0; padding: 24px; background: rgba(18,18,16,.66); backdrop-filter: blur(9px); display: grid; place-items: center; animation: fade .18s both; }
+@keyframes fade { from { opacity: 0; } }
+.modal__card { position: relative; width: min(920px,100%); max-height: min(720px,calc(100vh - 48px)); overflow: hidden; border-radius: 20px; background: var(--card); display: grid; grid-template-columns: 1.1fr .9fr; box-shadow: 0 30px 100px rgba(0,0,0,.3); }
+.modal__close { position: absolute; z-index: 2; top: 12px; right: 12px; width: 36px; height: 36px; border-radius: 50%; background: rgba(255,255,255,.9); display: grid; place-items: center; }
+.modal__close svg { width: 18px; }
+.modal__media { min-height: 500px; background: #d5d3cb; }
+.modal__media img { width: 100%; height: 100%; object-fit: cover; }
+.modal__content { padding: clamp(30px,4vw,56px); display: flex; flex-direction: column; justify-content: center; }
+.modal__content h2 { margin: 9px 0 14px; font-size: clamp(30px,4vw,48px); line-height: .98; letter-spacing: -.06em; }
+.modal__content > p { margin: 0; color: var(--ink-2); line-height: 1.65; }
+.modal__content dl { margin: 28px 0; padding: 17px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); display: grid; grid-template-columns: repeat(3,1fr); }
+.modal__content dl div { display: flex; flex-direction: column; gap: 3px; }
+.modal__content dt { color: var(--ink-3); font: 500 8px var(--mono); text-transform: uppercase; letter-spacing: .1em; }
+.modal__content dd { margin: 0; font-size: 12px; font-weight: 650; }
+.modal__actions { display: flex; gap: 8px; }
+.modal__actions .button { flex: 1; }
+.icon-button { width: 43px; height: 43px; border: 1px solid var(--line); border-radius: 11px; display: grid; place-items: center; }
+.icon-button svg { width: 17px; }
+.modal__content .text-link { margin-top: 18px; justify-content: center; }
+
+/* Toast */
+.toast { position: fixed; z-index: 100; left: calc(var(--side-width) + (100vw - var(--side-width))/2); bottom: 25px; padding: 10px 15px 10px 12px; border: 1px solid rgba(255,255,255,.13); border-radius: 11px; background: var(--ink); color: white; box-shadow: 0 9px 35px rgba(0,0,0,.22); display: flex; align-items: center; gap: 9px; font-size: 12px; opacity: 0; transform: translate(-50%,15px); pointer-events: none; transition: .25s var(--ease); }
+.toast.is-visible { opacity: 1; transform: translate(-50%,0); }
+.toast > span { width: 7px; height: 7px; border-radius: 50%; background: var(--lime); }
+
+/* Detail */
+.detail-page, .cart-page, .analytics-page { padding: clamp(24px,4vw,60px); min-height: 100vh; }
+.back-link { display: inline-block; margin-bottom: 30px; color: var(--ink-2); font-size: 12px; font-weight: 600; }
+.detail-grid { max-width: 1180px; margin: 0 auto; display: grid; grid-template-columns: minmax(340px,.9fr) minmax(390px,1.1fr); gap: clamp(45px,7vw,100px); align-items: center; }
+.detail-media { position: relative; overflow: hidden; border-radius: 18px; background: #d7d4ca; box-shadow: 0 18px 60px rgba(18,18,16,.12); }
+.detail-media img { width: 100%; max-height: 73vh; aspect-ratio: var(--ratio); object-fit: cover; }
+.detail-media span { position: absolute; top: 14px; left: 14px; padding: 6px 9px; border-radius: 7px; background: var(--ink); color: white; font: 500 9px var(--mono); text-transform: uppercase; }
+.detail-copy h1 { max-width: 650px; margin: 10px 0 18px; font-size: clamp(43px,6vw,80px); line-height: .94; letter-spacing: -.065em; }
+.detail-copy .lede { max-width: 600px; margin: 0; color: var(--ink-2); font-size: 17px; line-height: 1.65; }
+.detail-stats { margin: 27px 0; display: grid; grid-template-columns: repeat(3,1fr); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
+.detail-stats div { padding: 16px 8px 16px 0; display: flex; flex-direction: column; }
+.detail-stats strong { font-size: 15px; }
+.detail-stats span { color: var(--ink-3); font-size: 10px; }
+.prompt-sample { position: relative; padding: 18px; border: 1px solid var(--line); border-radius: 14px; background: rgba(255,255,255,.55); overflow: hidden; }
+.prompt-sample > div:first-child { display: flex; justify-content: space-between; color: var(--ink-3); font: 500 8px var(--mono); text-transform: uppercase; letter-spacing: .1em; }
+.prompt-sample p { margin: 17px 0 4px; font: 12px/1.65 var(--mono); }
+.prompt-fade { position: absolute; inset: auto 0 0; height: 45px; padding-top: 20px; background: linear-gradient(transparent,#f7f6f1 55%); color: var(--ink-3); font: 500 8px var(--mono); text-align: center; text-transform: uppercase; }
+.purchase-row { margin-top: 18px; display: flex; gap: 8px; }
+.purchase-row .button { flex: 1; }
+.save-large { min-width: 100px; border: 1px solid var(--line); border-radius: 11px; display: flex; align-items: center; justify-content: center; gap: 8px; font-size: 12px; font-weight: 650; }
+.save-large svg { width: 16px; }
+.save-large.is-active { background: white; }
+.save-large.is-active svg { fill: var(--lime); }
+.fine-print { display: flex; align-items: center; justify-content: center; gap: 7px; color: var(--ink-3); font-size: 9px; }
+.fine-print svg { width: 13px; color: #6f9407; }
+
+/* Cart */
+.cart-page { max-width: 1160px; margin: 0 auto; }
+.page-title { margin: 10px 0 42px; }
+.cart-layout { display: grid; grid-template-columns: 1fr 340px; gap: 30px; align-items: start; }
+.cart-items { border-top: 1px solid var(--line); }
+.cart-item { padding: 17px 0; border-bottom: 1px solid var(--line); display: grid; grid-template-columns: 78px 1fr auto 35px; align-items: center; gap: 16px; }
+.cart-item img { width: 78px; height: 82px; border-radius: 10px; object-fit: cover; }
+.cart-item > div { display: flex; flex-direction: column; }
+.cart-item > div span { color: var(--ink-3); font: 500 8px var(--mono); text-transform: uppercase; letter-spacing: .08em; }
+.cart-item > div a { margin: 5px 0 3px; font-size: 16px; font-weight: 650; letter-spacing: -.02em; }
+.cart-item small { color: var(--ink-2); }
+.cart-item > strong { font-size: 13px; }
+.cart-item > button { width: 32px; height: 32px; border-radius: 8px; color: var(--ink-3); display: grid; place-items: center; }
+.cart-item > button:hover { background: rgba(0,0,0,.05); color: var(--ink); }
+.cart-item > button svg { width: 16px; }
+.summary-card { position: sticky; top: 35px; padding: 25px; border-radius: 16px; background: var(--side); border: 1px solid var(--line); box-shadow: 0 12px 45px rgba(18,18,16,.05); }
+.summary-card h2 { margin: 0 0 23px; font-size: 18px; letter-spacing: -.03em; }
+.summary-card > div { margin: 10px 0; display: flex; justify-content: space-between; color: var(--ink-2); font-size: 12px; }
+.summary-card > div strong { color: var(--ink); }
+.summary-card .summary-total { margin-top: 20px; padding-top: 17px; border-top: 1px solid var(--line); color: var(--ink); font-size: 15px; }
+.summary-card .summary-total strong { font-size: 20px; }
+.summary-card .button { width: 100%; margin-top: 16px; }
+.summary-card > p { display: flex; align-items: center; justify-content: center; gap: 5px; color: var(--ink-3); font-size: 9px; }
+.summary-card > p svg { width: 12px; }
+.success-card { max-width: 560px; min-height: 390px; margin: 55px auto; padding: 55px; border: 1px solid var(--line); border-radius: 19px; background: var(--side); display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
+.success-card > span { width: 55px; height: 55px; margin-bottom: 22px; border-radius: 50%; background: var(--lime); display: grid; place-items: center; }
+.success-card > span svg { width: 25px; }
+.success-card h2 { margin: 8px 0; font-size: 31px; letter-spacing: -.05em; }
+.success-card > p:not(.eyebrow) { max-width: 340px; margin: 0 0 22px; color: var(--ink-2); }
+
+/* Analytics */
+.analytics-page { max-width: 1380px; margin: 0 auto; }
+.analytics-head { margin: 7px 0 35px; display: flex; align-items: end; justify-content: space-between; gap: 25px; }
+.analytics-head > div > p:last-child { margin: 11px 0 0; color: var(--ink-2); }
+.metrics { margin-bottom: 18px; display: grid; grid-template-columns: repeat(4,1fr); gap: 12px; }
+.metrics article { min-height: 142px; padding: 21px; border: 1px solid var(--line); border-radius: 14px; background: rgba(255,255,255,.55); display: flex; flex-direction: column; }
+.metrics p { margin: 0; color: var(--ink-2); font-size: 11px; }
+.metrics strong { margin: auto 0 3px; font-size: 30px; letter-spacing: -.055em; }
+.metrics span { color: #638700; font: 500 9px var(--mono); }
+.analytics-grid { display: grid; grid-template-columns: 1.45fr 1fr; gap: 12px; }
+.panel { padding: 23px; border: 1px solid var(--line); border-radius: 14px; background: rgba(255,255,255,.58); }
+.panel-title { display: flex; align-items: start; justify-content: space-between; }
+.panel-title h2 { margin: 4px 0 0; font-size: 18px; letter-spacing: -.03em; }
+.panel-title > span { color: var(--ink-3); font: 500 8px var(--mono); }
+.chart-bars { height: 225px; margin: 30px 0 0; border-bottom: 1px solid var(--line); display: flex; align-items: end; gap: clamp(5px,1vw,13px); }
+.chart-bars > div { height: 100%; flex: 1; display: flex; flex-direction: column; justify-content: end; gap: 8px; text-align: center; }
+.chart-bars span { width: 100%; min-height: 3px; border-radius: 5px 5px 0 0; background: var(--ink); transition: background .18s; }
+.chart-bars > div:hover span { background: #82ae08; }
+.chart-bars small { height: 17px; color: var(--ink-3); font: 8px var(--mono); }
+.data-list { margin-top: 21px; }
+.data-list > div { min-height: 53px; border-top: 1px solid var(--line-2); display: flex; align-items: center; gap: 12px; }
+.data-list .rank { color: var(--ink-3); font: 500 8px var(--mono); }
+.data-list strong { display: flex; flex-direction: column; font-size: 12px; }
+.data-list strong small { color: var(--ink-3); font-size: 9px; font-weight: 400; }
+.data-list b { margin-left: auto; font-size: 11px; }
+.category-panel { max-height: 410px; overflow: hidden; }
+.creator-note { position: relative; overflow: hidden; background: var(--ink); color: white; display: flex; flex-direction: column; justify-content: center; }
+.creator-note > svg { position: absolute; top: -10px; right: -10px; width: 145px; opacity: .07; }
+.creator-note h2 { max-width: 420px; margin: 8px 0; font-size: 31px; line-height: 1.05; letter-spacing: -.05em; }
+.creator-note > p:not(.eyebrow) { max-width: 430px; color: #aaa99f; font-size: 12px; }
+.creator-note .text-link { margin-top: 15px; color: var(--lime); }
+
+@media (max-width: 1260px) {
+  .masonry { columns: 4 205px; }
+  .model-tabs button { padding: 0 10px; }
+}
+@media (max-width: 1050px) {
+  .model-tabs button { width: 38px; padding: 0; justify-content: center; font-size: 0; }
+  .model-tabs button:first-child { width: 58px; font-size: 12px; }
